import {confirmButtonResult} from './button-feedback.js';
import {ASTRAL_RELICS,ASTRAL_COST,ASTRAL_SLOTS,rollAstral as domainRoll,chooseAstral as domainChoose,equipAstral as domainEquip} from './astral.js';
import {RELICS,buyRelic as domainBuy} from './pillars.js';
import {RELIC_FILTERS,filteredRelicIds} from './relic-filters.js';
import {RARE_RELIC_DESCRIPTION} from './relic-classification.js';
import {RELIQUARY_ART as ART} from './approved-reliquary-assets.js';
import {serviceShadow} from './approved-service-host.js';
export function mountApprovedReliquary(dialog,state,{initialUi={},onUiState,onChange,onClose,onCommand=()=>{},beforeAction=()=>false,softMode=()=>false}){
 const shadow=serviceShadow(dialog,`<div id="gv-reliquary-service"><div class="scene"><section class="window" id="gr-window"><header class="head"><img id="gr-emblem" alt=""><h2>Relicário</h2><div class="wallet" aria-label="Estrelas disponíveis"><img id="gr-star" alt="Estrelas"><span id="gr-stars"></span></div><button type="button" class="button close cursor-interaction" id="gr-close" aria-label="Fechar Relicário">×</button></header><section class="equipped" aria-label="Relíquias equipadas"><div class="equipped-label">Equipados <span id="gr-equipped-count"></span></div><div class="slots" id="gr-slots"></div></section><nav class="views" aria-label="Áreas do Relicário"><div class="view-tabs" role="tablist" aria-label="Áreas"><button type="button" class="button view cursor-interaction" role="tab" id="gr-tab-discover" data-view="discover" aria-controls="gr-panel" aria-selected="true">Descobrir</button><button type="button" class="button view cursor-interaction" role="tab" id="gr-tab-collection" data-view="collection" aria-controls="gr-panel" aria-selected="false">Coleção</button><button type="button" class="button view cursor-interaction" role="tab" id="gr-tab-founders" data-view="founders" aria-controls="gr-panel" aria-selected="false">Fundadoras</button></div><select class="view-select" id="gr-view-select" aria-label="Área do Relicário"><option value="discover">Descobrir</option><option value="collection">Coleção</option><option value="founders">Fundadoras</option></select><button type="button" class="button help-trigger cursor-interaction" id="gr-help" aria-label="Como funciona">?</button></nav><div class="workspace"><section id="gr-panel" class="panel" role="tabpanel" aria-labelledby="gr-tab-discover"></section><section class="help-panel" id="gr-help-panel" aria-label="Como funciona" hidden></section></div><footer class="footer"><span class="label" id="gr-progress-label">Relíquias descobertas</span><strong class="count" id="gr-count"></strong><div class="track" role="progressbar" id="gr-progress" aria-label="Relíquias descobertas" aria-valuemin="0"><span id="gr-fill"></span></div></footer><div class="live" id="gr-live" role="status" aria-live="polite"></div></section></div></div>`),css=dialog.ownerDocument.createElement('link');css.rel='stylesheet';css.href='approved-reliquary-ui.css';shadow.prepend(css);
 const root=shadow.querySelector('#gv-reliquary-service'),q=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)],reduced=matchMedia('(prefers-reduced-motion:reduce)');
 const DATA={filters:RELIC_FILTERS,filterIds:Object.fromEntries(Object.keys(RELIC_FILTERS).map(f=>[f,filteredRelicIds(ASTRAL_RELICS,state.astral,f)])),rareDescription:RARE_RELIC_DESCRIPTION};
 let view=state.astral.offer.length?'discover':['discover','collection','founders'].includes(initialUi.view)?initialUi.view:'discover',filter=Object.hasOwn(RELIC_FILTERS,initialUi.filter)?initialUi.filter:'all',page=Math.max(0,Math.min(29,initialUi.page||0)),offerPage=0,founderPage=Math.max(0,Math.min(2,initialUi.founderPage||0)),help=false,capacity=10,busy=false,disposed=false;
 const isSoft=()=>softMode()||reduced.matches,remember=()=>onUiState?.({view,filter,page,founderPage});
 function commit(action,...args){if(disposed||beforeAction())return false;const ok=action(state,...args);if(ok){onChange();confirmButtonResult(root.ownerDocument,action===domainEquip?'set':'craft');}return ok;}
 const rollAstral=()=>commit(domainRoll),chooseAstral=(_s,id)=>commit(domainChoose,id),equipAstral=(_s,id)=>commit(domainEquip,id),buyRelic=(_s,id)=>commit(domainBuy,id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),title=s=>s.toLocaleLowerCase('pt-BR').replace(/(^|\s)([a-zà-ÿ])/g,(m,a,b)=>a+b.toLocaleUpperCase('pt-BR')).replace(/\b(Do|Da|De|Em|Dos|Das)\b/g,m=>m.toLowerCase()),image=(id,cls='')=>`<img src="${ART[id]}" alt="" class="${cls}" draggable="false">`,button=(text,attrs='',cls='')=>`<button type="button" class="button cursor-interaction ${cls}" ${attrs}>${text}</button>`,byId=id=>ASTRAL_RELICS.find(r=>r.id===id),filters={...DATA.filters,rare:'Veios raros'};
function announce(text){q('#gr-live').textContent=text;}
function shown(){return ASTRAL_RELICS.filter(r=>DATA.filterIds[filter].includes(r.id));}
function pulse(selector,cls='pop'){if(isSoft())return;all(selector).forEach(el=>{el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);});}
function slots(){q('#gr-equipped-count').textContent=state.astral.equipped.length+'/'+ASTRAL_SLOTS;q('#gr-slots').innerHTML=Array.from({length:ASTRAL_SLOTS},(_,i)=>{const r=byId(state.astral.equipped[i]);return `<button type="button" class="slot cursor-interaction ${r?'':'empty'}" ${r?`data-remove="${r.id}" aria-label="Remover ${esc(title(r.name))} dos equipados"`:'data-open-collection="true" aria-label="Escolher uma relíquia para equipar"'}>${r?image(r.id):'<span class="empty-symbol" aria-hidden="true">+</span>'}<span class="slot-name">${r?esc(title(r.name)):'Livre'}</span>${r?'<span class="remove" aria-hidden="true">×</span>':''}</button>`;}).join('');}
function pager(kind,index,count){return `<nav class="pager ${kind==='collection'?'':'offer-pager'}" aria-label="${kind==='collection'?'Páginas da coleção':kind==='offer'?'Opções da oferta':'Relíquias fundadoras'}">${button('‹',`data-page-kind="${kind}" data-page-step="-1" aria-label="Anterior" ${index<=0?'disabled':''}`)}<span>${index+1} / ${count}</span>${button('›',`data-page-kind="${kind}" data-page-step="1" aria-label="Próximo" ${index>=count-1?'disabled':''}`)}</nav>`;}
function responsiveOption(index,current){return root.getBoundingClientRect().width<=650&&index!==current?' hidden':'';}
function discover(){
 const a=state.astral,remaining=ASTRAL_RELICS.length-a.owned.length;
 if(a.offer.length){offerPage=Math.min(offerPage,a.offer.length-1);return `<header class="offer-head"><h3>Escolha 1</h3><span class="saved">✓ Oferta guardada</span></header><div class="options">${a.offer.map((id,i)=>{const r=byId(id);return `<article class="option" data-option="${id}"${responsiveOption(i,offerPage)}>${image(id)}<h3>${esc(title(r.name))}</h3><p>${esc(r.text)}</p>${button('Escolher',`data-choose="${id}" aria-label="Escolher ${esc(title(r.name))}"`,'primary')}</article>`;}).join('')}</div>${pager('offer',offerPage,a.offer.length)}`;}
 const last=a.last&&byId(a.last),complete=remaining===0,can=state.stars>=ASTRAL_COST&&!complete&&a.rolls<1000000;
 return `<div class="summon"><div class="summon-art ${last?'acquired':''}">${image(last?last.id:'vignette')}</div><section class="summon-copy"><span class="result-tag">${last?(a.equipped.includes(last.id)?'✓ Equipado':'✓ Na coleção'):complete?'✓ Todas descobertas':''}</span><h3>${complete?'Coleção completa':last?esc(title(last.name)):Math.min(3,remaining)+' opções · 1 escolha'}</h3><p>${complete?'Troque seus equipados na coleção.':last?esc(last.text):'O efeito fica ativo ao equipar.'}</p>${complete?'':`<div class="price" aria-label="${ASTRAL_COST} estrelas por invocação">${image('star')} ${ASTRAL_COST}</div>`}${complete?button('Ver coleção','data-open-collection="true"','primary'):button('Invocar',`id="gr-invoke" ${can?'':'disabled'}`,'primary')}${last&&!complete?button('Ver na coleção','id="gr-open-last"'):''}<span class="notice">${!complete&&!can?(a.rolls>=1000000?'Limite de invocações':'Estrelas insuficientes'):''}</span></section></div>`;
}
function collection(){
 const list=shown(),pages=Math.max(1,Math.ceil(list.length/capacity));page=Math.min(page,pages-1);const hint=filter==='rare'?DATA.rareDescription:state.astral.equipped.length>=ASTRAL_SLOTS?'Remova um equipado para abrir espaço.':'';
 return `<div class="collection"><nav class="filters" aria-label="Filtrar coleção">${Object.entries(filters).map(([id,label])=>button(esc(label),`data-filter="${id}" aria-pressed="${filter===id}"`,'filter')).join('')}</nav><select class="filter-select" id="gr-filter-select" aria-label="Filtrar coleção">${Object.entries(filters).map(([id,label])=>`<option value="${id}"${filter===id?' selected':''}>${esc(label)}</option>`).join('')}</select><p class="collection-hint">${esc(hint)}</p><div class="relic-grid" id="gr-grid">${list.slice(page*capacity,(page+1)*capacity).map(r=>{const owned=state.astral.owned.includes(r.id),equipped=state.astral.equipped.includes(r.id),full=!equipped&&state.astral.equipped.length>=ASTRAL_SLOTS,label=equipped?'Remover':!owned?'Não descoberta':full?'3/3 ocupados':'Equipar';return `<button type="button" class="relic-card cursor-interaction ${owned?'owned':'unknown'} ${equipped?'equipped':''}" data-equip="${r.id}" aria-pressed="${equipped}" aria-label="${esc(title(r.name)+'. '+r.text+' '+label)}" ${!owned||full?'disabled':''}>${image(r.id)}<strong>${esc(title(r.name))}</strong><span class="benefit">${esc(r.text)}</span><span class="card-state">${equipped?'◆ ':owned?'✓ ':''}${label}</span></button>`;}).join('')}</div>${pager('collection',page,pages)}</div>`;
}
function founders(){return `<div class="founders" style="height:100%"><p class="founder-hint">Sempre ativas · não usam espaços</p><div class="options">${RELICS.map((r,i)=>{const owned=state.relics.includes(r.id);return `<article class="option" data-founder-card="${r.id}"${responsiveOption(i,founderPage)}>${image(r.id)}<h3>${esc(title(r.name))}</h3><p>${esc(r.detail)}</p><div class="price">${owned?'':image('star')+' '+r.cost}</div>${button(owned?'✓ Ativa':'Despertar',`data-founder="${r.id}" aria-label="${esc((owned?'Ativa: ':'Despertar ')+title(r.name))}" ${owned||state.stars<r.cost?'disabled':''}`,'primary')}</article>`;}).join('')}</div>${pager('founder',founderPage,RELICS.length)}</div>`;}
function renderPanel(){q('#gr-panel').setAttribute('aria-labelledby','gr-tab-'+view);q('#gr-panel').innerHTML=view==='discover'?discover():view==='collection'?collection():founders();}
function renderHelp(){q('#gr-help-panel').hidden=!help;if(!help)return;q('#gr-help-panel').innerHTML=`<header><h3>Como funciona</h3>${button('×','id="gr-help-close" aria-label="Voltar ao Relicário"','close')}</header><p><strong>${ASTRAL_COST} estrelas → até 3 opções → 1 relíquia.</strong></p><p>Até 5 estrelas por andar da campanha.</p><p>A oferta fica guardada ao fechar. Escolher não cobra novamente.</p><p><strong>Até 3 equipadas.</strong> Troque na coleção ou remova pelo × de um espaço ocupado.</p><p><strong>Fundadoras:</strong> ficam sempre ativas, sem ocupar espaços.</p>${Object.values(state.starUpgrades).some(n=>n>0)?'<p><strong>Melhorias anteriores:</strong> seus bônus estelares continuam ativos.</p>':''}`;}
function render(){root.dataset.soft=String(isSoft());q('#gr-emblem').src=ART.emblem;q('#gr-star').src=ART.star;q('#gr-stars').textContent=state.stars.toLocaleString('pt-BR');q('#gr-view-select').value=view;slots();all('[data-view]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.view===view));b.classList.toggle('pending',b.dataset.view==='discover'&&state.astral.offer.length>0);});renderPanel();renderHelp();const isFounder=view==='founders',n=isFounder?state.relics.length:state.astral.owned.length,total=isFounder?RELICS.length:ASTRAL_RELICS.length;q('#gr-count').textContent=n+'/'+total;q('#gr-progress-label').textContent=isFounder?'Fundadoras ativas':'Relíquias descobertas';q('#gr-progress').setAttribute('aria-label',isFounder?'Fundadoras ativas':'Relíquias descobertas');q('#gr-progress').setAttribute('aria-valuemax',total);q('#gr-progress').setAttribute('aria-valuenow',n);q('#gr-fill').style.width=100*n/total+'%';}
function setView(next){view=next;help=false;announce('');render();remember();}
function equip(id){if(!equipAstral(state,id))return;render();announce(state.astral.equipped.includes(id)?'Equipado: '+title(byId(id).name):'Removido dos equipados.');pulse('[data-remove="'+id+'"],[data-equip="'+id+'"]');(q('[data-equip="'+id+'"]:not(:disabled)')||q('#gr-tab-collection')).focus({preventScroll:true});remember();}
root.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b||b.disabled||busy||disposed)return;onCommand();
 if(b.dataset.view){setView(b.dataset.view);return;}
 if(b.dataset.openCollection){setView('collection');return;}
 if(b.dataset.filter){filter=b.dataset.filter;page=0;renderPanel();q('[data-filter="'+filter+'"]').focus({preventScroll:true});remember();return;}
 if(b.dataset.pageKind){const kind=b.dataset.pageKind,step=Number(b.dataset.pageStep);if(kind==='collection')page+=step;else if(kind==='offer')offerPage+=step;else founderPage+=step;renderPanel();q('[data-page-kind="'+kind+'"][data-page-step="'+(-step)+'"]')?.focus({preventScroll:true});remember();return;}
 if(b.id==='gr-invoke'){if(event.detail>1)return;busy=true;try{if(rollAstral(state)){offerPage=0;render();pulse('.option','reveal');q('#gr-tab-discover').focus({preventScroll:true});announce('Oferta guardada. Escolha uma relíquia.');remember();}}finally{busy=false;}return;}
 if(b.dataset.choose){if(event.detail>1)return;busy=true;try{if(chooseAstral(state,b.dataset.choose)){render();pulse('.summon-art,[data-remove="'+b.dataset.choose+'"]');q('#gr-open-last')?.focus({preventScroll:true});announce('Adquirida: '+title(byId(b.dataset.choose).name));remember();}}finally{busy=false;}return;}
 if(b.dataset.equip||b.dataset.remove){equip(b.dataset.equip||b.dataset.remove);return;}
 if(b.dataset.founder){if(event.detail>1)return;if(buyRelic(state,b.dataset.founder)){render();pulse('[data-founder-card="'+b.dataset.founder+'"]');announce('Ativa: '+title(RELICS.find(r=>r.id===b.dataset.founder).name));q('#gr-tab-founders').focus({preventScroll:true});remember();}return;}
 if(b.id==='gr-open-last'){filter='all';const index=ASTRAL_RELICS.findIndex(r=>r.id===state.astral.last);page=Math.floor(index/capacity);setView('collection');q('[data-equip="'+state.astral.last+'"]:not(:disabled)')?.focus({preventScroll:true});return;}
 if(b.id==='gr-help'){help=true;renderHelp();q('#gr-help-close').focus({preventScroll:true});return;}
 if(b.id==='gr-help-close'){help=false;renderHelp();q('#gr-help').focus({preventScroll:true});return;}
 if(b.id==='gr-close'){onClose();return;}
});
root.addEventListener('change',event=>{if(event.target.id==='gr-view-select')setView(event.target.value);else if(event.target.id==='gr-filter-select'){filter=event.target.value;page=0;renderPanel();q('#gr-filter-select').focus({preventScroll:true});remember();}});
root.addEventListener('keydown',event=>{if(event.key!=='Escape')return;event.preventDefault();event.stopPropagation();if(help){help=false;renderHelp();q('#gr-help').focus({preventScroll:true});}else onClose();});
render();let widthClass=0;
const resize=new ResizeObserver(()=>{if(disposed)return;const w=root.getBoundingClientRect().width,next=w<=400?2:w<=650?4:w<=900?6:w<=1000?8:10,group=w<=650?1:2;if(capacity!==next){const start=page*capacity;capacity=next;page=Math.floor(start/capacity);if(view==='collection')renderPanel();}if(group!==widthClass){widthClass=group;if(view!=='collection')renderPanel();}});resize.observe(root);
const syncSoft=()=>{root.dataset.soft=String(isSoft());};reduced.addEventListener('change',syncSoft);q('#gr-close').focus({preventScroll:true});return ()=>{disposed=true;resize.disconnect();reduced.removeEventListener('change',syncSoft);root.getAnimations({subtree:true}).forEach(a=>a.cancel());};
}
